## Task: Port js/wordfreq.js to TypeScript with TDD

### Context
Read `scripts/slop-score/prompt.md` for full project context.

### Prerequisites
- Task #1 (project structure) must be complete
- Task #2 (data files) must be complete

### What to do

#### Step 1: Write tests first
Create `scripts/slop-score/src/__tests__/wordfreq.test.ts`:

```typescript
import { describe, test, expect, beforeAll } from 'bun:test';
import { Wordfreq, loadWordfreq } from '../lib/wordfreq';
import { join, dirname } from 'path';

const DATA_DIR = join(dirname(import.meta.path), '../../data');

describe('Wordfreq', () => {
  let wf: Wordfreq;

  beforeAll(async () => {
    wf = await loadWordfreq(DATA_DIR);
  });

  test('loads wordfreq data', () => {
    expect(wf).toBeDefined();
  });

  test('returns frequency for common words', () => {
    const freq = wf.getFrequency('the');
    expect(freq).toBeGreaterThan(0);
  });

  test('returns 0 for unknown words', () => {
    const freq = wf.getFrequency('xyzabc123notaword');
    expect(freq).toBe(0);
  });

  test('returns zipf score', () => {
    const zipf = wf.getZipf('the');
    expect(zipf).toBeGreaterThan(5); // Common words have high zipf
  });

  test('zipf for rare words is lower', () => {
    const theZipf = wf.getZipf('the');
    const rareZipf = wf.getZipf('antidisestablishmentarianism');
    expect(theZipf).toBeGreaterThan(rareZipf);
  });
});
```

#### Step 2: Implement the module
Create `scripts/slop-score/src/lib/wordfreq.ts` by porting from `js/wordfreq.js`:

Key requirements:
- Load `large_en.msgpack.gz` using Bun's gunzipSync and @msgpack/msgpack
- Implement `Wordfreq` class with frequency lookup methods
- Export `loadWordfreq(dataDir: string): Promise<Wordfreq>`

```typescript
import { gunzipSync } from 'bun';
import { decode } from '@msgpack/msgpack';
import { join } from 'path';

export class Wordfreq {
  private data: Map<string, number>;

  constructor(data: Map<string, number>) {
    this.data = data;
  }

  getFrequency(word: string): number {
    return this.data.get(word.toLowerCase()) ?? 0;
  }

  getZipf(word: string): number {
    // Implement zipf calculation from js/wordfreq.js
  }
}

export async function loadWordfreq(dataDir: string): Promise<Wordfreq> {
  const compressed = await Bun.file(join(dataDir, 'large_en.msgpack.gz')).arrayBuffer();
  const decompressed = gunzipSync(new Uint8Array(compressed));
  const data = decode(decompressed) as Record<string, number>;
  return new Wordfreq(new Map(Object.entries(data)));
}
```

